import { ensureLayerModel, baseGaps, networkGaps, closeResolvedWork, runPagesRoutine, queueLayerDiscovery, demonstrateAgentRun, updateDocument, updateConnection, updateRoutine } from './layer-core.js';
import { renderLayerBoard, renderRoutines as renderLayerRoutines, renderConnections, renderKnowledge } from './layer-pages-ui.js';
const KEY = 'aludel-layer-app-trial-v3';
const fresh = () => ({ project: 'Untitled site', pages: [], flows: [], sources: [], insights: [], layers: [], work: [], policy: { storyFlows: false, revision: 1 }, execution: { adapter: 'symphony', agentEnabled: false }, audit: null });
let state;
try { state = JSON.parse(localStorage.getItem(KEY)) || fresh(); } catch { state = fresh(); }
ensureLayerModel(state);
const ui = { view: 'home', tab: '', operation: 'board', page: null, flow: null, step: 0, phone: false, query: '', routine: null, run: null, connection: null, doc: null, outputDoc: null, boardFilter: 'all', runFilter: 'all' };
const root = document.querySelector('#app');
const id = prefix => `${prefix}-${Math.random().toString(36).slice(2, 9)}`;
const h = value => String(value ?? '').replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
let lastOutputSignature = JSON.stringify([state.pages,state.flows]);
let mapTimer;
const save = () => { closeResolvedWork(state); localStorage.setItem(KEY, JSON.stringify(state)); const signature=JSON.stringify([state.pages,state.flows]); if(signature!==lastOutputSignature){lastOutputSignature=signature;clearTimeout(mapTimer);mapTimer=setTimeout(()=>{const run=runPagesRoutine(state,'map-coverage','After page/flow change · quiet period');if(run){localStorage.setItem(KEY,JSON.stringify(state));render();}},1800);} };
const queueSync = trigger => { if(state.pagesApp.connections.some(x=>x.status==='active')&&!state.pagesApp.runs.some(x=>x.routineId==='network-sync'&&x.status==='ready'))runPagesRoutine(state,'network-sync',trigger); };
const findPage = key => state.pages.find(page => page.id === key);
const findFlow = key => state.flows.find(flow => flow.id === key);
const findLayer = key => state.layers.find(layer => layer.id === key);
const stories = () => state.layers.filter(layer => layer.type === 'vision').flatMap(layer => layer.records.map(record => ({ ...record, layer: layer.name })));
const date = () => new Date().toLocaleString();
const pageOptions = selected => `<option value="">Choose a page…</option>${state.pages.map(page => `<option value="${h(page.id)}" ${selected === page.id ? 'selected' : ''}>${h(page.name)}</option>`).join('')}`;
const refOptions = selected => `<option value="">No link yet</option>${state.pages.map(page => `<option value="page:${h(page.id)}" ${selected === `page:${page.id}` ? 'selected' : ''}>Page · ${h(page.name)}</option>`).join('')}${state.flows.map(flow => `<option value="flow:${h(flow.id)}" ${selected === `flow:${flow.id}` ? 'selected' : ''}>Flow · ${h(flow.name)}</option>`).join('')}${state.layers.flatMap(layer => layer.records.map(record => `<option value="record:${h(layer.id)}:${h(record.id)}" ${selected === `record:${layer.id}:${record.id}` ? 'selected' : ''}>${h(layer.name)} · ${h(record.title)}</option>`)).join('')}`;
const tabs = (names, current, utility = false) => `<div class="tabs ${utility ? 'utility' : ''}" role="tablist">${names.map(([key, label]) => `<button type="button" role="tab" aria-selected="${current === key}" data-action="tab" data-tab="${key}">${label}</button>`).join('')}</div>`;
const badge = (label, kind = '') => `<span class="badge ${kind}">${h(label)}</span>`;
const empty = (title, body, action, label) => `<div class="empty"><h2>${h(title)}</h2><p class="lead">${h(body)}</p>${action ? `<button class="btn green" data-action="${action}">${h(label)}</button>` : ''}</div>`;
function navigation() {
  const open=state.work.filter(item=>['suggested','ready'].includes(item.status)).length;
  return `<aside class="rail"><div class="brand">◇ Aludel</div><div class="project"><strong>${h(state.project)}</strong><small>Pages-first local trial</small></div><nav aria-label="Project navigation"><button class="nav home-nav ${ui.view==='home'?'active':''}" data-action="nav" data-view="home"><span class="dot"></span> Home</button><div class="nav-divider"></div><div class="nav-label">Layers</div><button class="nav ${ui.view==='pages'?'active':''}" data-action="nav" data-view="pages" data-tab="map"><span class="dot"></span> Pages</button>${state.layers.map(layer=>`<button class="nav ${ui.view===layer.id?'active':''}" data-action="nav" data-view="${h(layer.id)}"><span class="dot" style="background:#8a6100"></span>${h(layer.name)}</button>`).join('')}<div class="nav-divider"></div><div class="nav-label">Utilities</div><button class="nav utility ${ui.view==='library'?'active':''}" data-action="nav" data-view="library"><span class="dot"></span> Library</button><button class="nav utility ${ui.view==='work'?'active':''}" data-action="nav" data-view="work"><span class="dot"></span> Work ${open?badge(open,'purple'):''}</button></nav><div class="spacer"></div><button class="nav" data-action="reset">Reset trial</button><div class="foot">Saved only in this browser. No agent or external service is connected.</div></aside>`;
}
function render() {
  root.innerHTML=`<div class="shell">${navigation()}<div><header class="top"><input class="search-input" aria-label="Search project knowledge" placeholder="Search pages, flows, sources, insights…" value="${h(ui.query)}" data-field="search"><button class="btn" data-action="search">Search</button><span class="trial">Local interactive trial</span></header><main class="main">${ui.view==='home'?renderHome():ui.view==='pages'?renderPages():ui.view==='library'?renderLibrary():ui.view==='work'?renderWork():renderLayer(findLayer(ui.view))}<p class="footer-note">Prototype for a UX designer trial. Changes are local to this browser; agent scheduling and external integrations are represented but do not run.</p></main></div></div>`;
}
function renderHome() {
  const open=state.work.filter(item=>['suggested','ready'].includes(item.status));
  const cards=[`<div class="bento-card accent"><div class="row space"><span class="eyebrow">Pages layer</span>${badge(`${state.pages.length} pages`,'green')}</div><h2>Your site's experience</h2><p>Build the map, shape page mockups and connect them into flows.</p><div class="actions"><button class="btn green" data-action="nav" data-view="pages" data-tab="map">Open Pages</button><button class="btn" data-action="nav" data-view="pages" data-tab="operations">${state.work.filter(x=>x.layer==='Pages'&&['suggested','ready'].includes(x.status)).length} open items</button></div></div>`,...state.layers.filter(layer=>layer.homeCard!==false).map(layer=>`<div class="bento-card"><div class="row space"><span class="eyebrow">${h(layer.name)} layer</span>${badge(`${layer.records.length} ${layer.output}${layer.records.length===1?'':'s'}`,'blue')}</div><h2>${h(layer.name)}</h2><p>${h(layer.purpose||`Maintains ${layer.output} for this project.`)}</p><div class="actions"><button class="btn" data-action="nav" data-view="${h(layer.id)}">Open layer</button></div></div>`)];
  return `<div class="eyebrow">Project home</div><h1>${h(state.project)}</h1><p class="lead">Your layers, recent work and shared project tools in one place.</p><div class="home-bento">${cards.join('')}<div class="bento-card soft"><span class="eyebrow">Work across layers</span><h2>${open.length} open item${open.length===1?'':'s'}</h2><p>Work collects routine runs and output tasks from every layer.</p><button class="btn" data-action="nav" data-view="work">Open Work</button></div></div><section class="home-manage"><div class="row space"><div><h2>Manage layers</h2><p class="muted">Add a layer when the project needs another family of outputs. Decide whether it appears on Home.</p></div><button class="btn primary" data-action="home-add-layer">+ Add layer</button></div>${state.layers.length?state.layers.map(layer=>`<div class="home-layer-row"><div><strong>${h(layer.name)}</strong><span class="small muted"> · ${h(layer.output)} output · ${layer.records.length} records</span></div><label class="toggle small"><input type="checkbox" data-field="home-card" data-id="${h(layer.id)}" ${layer.homeCard!==false?'checked':''}> Show on Home</label></div>`).join(''):'<p class="muted">Pages is the starting layer. Add Vision or a custom layer whenever it helps.</p>'}<div class="home-add ${ui.homeAdding?'':'hidden'}">${renderAddLayer()}</div></section>`;
}
function renderPages() {
  const title=`<div class="eyebrow">Layer app · Pages</div><h1>${h(state.project)}'s pages</h1><p class="lead">Plan the site's structure, mock up pages, and walk through its flows.</p>`;
  const helpers={h,badge};
  const nav=`<div class="layer-tabs" role="tablist" aria-label="Pages layer sections"><div class="layer-work-tabs">${[['map','Map'],['pages','Pages'],['flows','Flows']].map(([key,label])=>`<button role="tab" aria-selected="${ui.tab===key}" data-action="tab" data-tab="${key}">${label}</button>`).join('')}</div><div class="layer-manage-tabs">${[['operations','Operations'],['knowledge','Knowledge']].map(([key,label])=>`<button role="tab" aria-selected="${ui.tab===key}" data-action="tab" data-tab="${key}">${label}</button>`).join('')}</div></div>`;
  return `${title}${nav}${ui.tab==='map'?renderMap():ui.tab==='pages'?renderPageWorkspace():ui.tab==='flows'?renderFlows():ui.tab==='knowledge'?renderKnowledge(state,ui,helpers):renderPagesOperations(helpers)}`;
}
function renderPagesOperations(helpers) {
  const app=state.pagesApp;
  if(ui.operation==='routines')return renderLayerRoutines(state,ui,helpers);
  if(ui.operation==='connections')return renderConnections(state,ui,helpers);
  const open=state.work.filter(item=>item.layer==='Pages'&&['suggested','ready'].includes(item.status)).length;
  return `<div class="ops-heading"><div><h2>Layer operations</h2><p class="muted">Track output work and routine runs. Manage the routines and connections that generate it.</p></div></div><div class="operations-layout"><section>${renderLayerBoard(state,ui,helpers)}</section><aside class="ops-sidebar"><div class="card"><div class="row space"><h3>Routines</h3>${badge(`${app.routines.length}`,'blue')}</div><p class="small muted">Utility checks and agent work run under Pages instructions.</p>${app.routines.slice(0,4).map(item=>`<button class="ops-link" data-action="open-routine" data-id="${h(item.id)}"><strong>${h(item.title)}</strong><small>${h(item.trigger)}</small></button>`).join('')}<button class="btn" data-action="operation" data-operation="routines">View all routines</button></div><div class="card"><div class="row space"><h3>Connections</h3>${badge(`${app.connections.filter(item=>item.status==='active').length} active`,'green')}</div><p class="small muted">How Pages interprets neighboring layers' outputs.</p>${state.layers.length?state.layers.map(layer=>{const doc=app.connections.find(x=>x.layerId===layer.id);return `<button class="ops-link" data-action="${doc?'open-connection':'draft-connection'}" data-id="${h(doc?.id||layer.id)}"><strong>${h(layer.name)} → Pages</strong><small>${h(doc?.status||'Undiscovered')}</small></button>`}).join(''):'<p class="small muted">No neighboring layers yet.</p>'}<button class="btn" data-action="operation" data-operation="connections">View all connections</button></div></aside></div>`;
}
function renderMap() {
  const flows = state.flows.map(flow => `<div class="list-item"><div class="row space"><strong>${h(flow.name)}</strong>${badge(flow.reviewed ? 'Reviewed' : 'Draft', flow.reviewed ? 'green' : 'warn')}</div><div class="flowline">${flow.steps.length ? flow.steps.map((step, index) => `<span class="step">${index + 1}. ${h(findPage(step.page)?.name || 'Missing page')}</span>${index < flow.steps.length - 1 ? '<span class="arrow">→</span>' : ''}`).join('') : '<span class="muted">No steps yet</span>'}</div><button class="btn" data-action="open-flow" data-id="${h(flow.id)}">Open flow</button></div>`).join('');
  return `<div class="actions"><button class="btn green" data-action="new-page">+ Page blank</button><button class="btn" data-action="new-flow">+ Flow</button><span class="muted small">A page can stand alone; no story is required.</span></div>${state.pages.length ? `<div class="grid side"><div class="map"><div class="map-grid">${state.pages.map(page => `<button class="map-node" data-action="open-page" data-id="${h(page.id)}"><span class="route">${h(page.path || '/')}</span><h3>${h(page.name)}</h3>${badge(page.sections.length ? 'Mockup' : 'Blank',page.sections.length ? 'green' : 'warn')}<div class="mock-mini">${h(page.sections[0]?.title || page.note || 'Add a section to shape this page')}</div></button>`).join('')}</div></div><div class="card"><h2>Flows on this map</h2>${flows || '<p class="muted">No flows yet. Connect pages in a flow when you know the journey.</p>'}<div class="divider"></div><h3>Project name</h3><form id="project-form" class="inline-form"><input name="name" aria-label="Project name" value="${h(state.project)}" required maxlength="70"><button class="btn" type="submit">Rename</button></form></div></div>` : `<div class="grid side">${empty('Start with a page blank','Give the site one place to begin. You can compose its sections and then connect pages into a flow.','new-page','Create a page')}<div class="card soft"><h2>What is here?</h2><p>Pages works from blank. Library can hold research and find all project knowledge. Work is ready to hold your own tasks or suggestions from Pages routines.</p><h3>Name your site</h3><form id="project-form" class="inline-form"><input name="name" aria-label="Project name" value="${h(state.project)}" required maxlength="70"><button class="btn" type="submit">Rename</button></form></div></div>`}`;
}
function renderPageWorkspace() {
  if (!state.pages.length) return empty('No pages yet','Create a page blank on the Map or here, then give it sections to make a mockup.','new-page','Create a page');
  const page = findPage(ui.page) || state.pages[0]; ui.page = page.id;
  return `<div class="actions"><label class="small">Page <select class="field-select" data-field="page-select">${state.pages.map(p => `<option value="${h(p.id)}" ${p.id === page.id ? 'selected' : ''}>${h(p.name)}</option>`).join('')}</select></label><button class="btn" data-action="new-page">+ Page</button><span class="muted small">Saved when you leave a field.</span></div><div class="editor"><div class="card controls"><h2>Page spec</h2><label class="field"><span>Name</span><input data-page-field="name" value="${h(page.name)}" maxlength="70"></label><label class="field"><span>Address</span><input data-page-field="path" value="${h(page.path)}" maxlength="100"></label><label class="field"><span>Purpose / note</span><textarea data-page-field="note">${h(page.note)}</textarea></label><div class="divider"></div><div class="row space"><h3>Sections</h3><button class="btn" data-action="add-section">+ Add</button></div>${page.sections.length ? page.sections.map((section, index) => `<div class="section-edit"><div class="row space"><strong>${index + 1}. ${h(section.kind)}</strong><button class="btn subtle danger" data-action="remove-section" data-id="${h(section.id)}">Remove</button></div><label class="field"><span>Type</span><select data-section-field="kind" data-id="${h(section.id)}">${['hero','content','cards','form'].map(kind => `<option value="${kind}" ${section.kind === kind ? 'selected' : ''}>${kind[0].toUpperCase() + kind.slice(1)}</option>`).join('')}</select></label><label class="field"><span>Heading</span><input data-section-field="title" data-id="${h(section.id)}" value="${h(section.title)}" maxlength="120"></label><label class="field"><span>Body</span><textarea data-section-field="body" data-id="${h(section.id)}">${h(section.body)}</textarea></label><label class="field"><span>Button or field label</span><input data-section-field="cta" data-id="${h(section.id)}" value="${h(section.cta)}" maxlength="70"></label></div>`).join('') : '<p class="muted">No sections. The mockup is intentionally blank.</p>'}</div><div class="stack"><div class="row space"><h2>Spec mockup</h2><label class="toggle"><input type="checkbox" data-field="phone" ${ui.phone ? 'checked' : ''}> Phone width</label></div><div class="preview-stage">${mockup(page, ui.phone)}</div><div class="notice">This is a page mockup from your spec. There is no built site or coding layer in this trial.</div></div></div>`;
}
function mockup(page, phone = false) {
  if (!page) return `<div class="mock-site ${phone ? 'phone' : ''}"><div class="blank">Choose a page to see its mockup.</div></div>`;
  return `<div class="mock-site ${phone ? 'phone' : ''}"><div class="browser">${h(page.path || '/')}</div><div class="site-nav"><strong>${h(state.project)}</strong><span>${state.pages.slice(0,3).map(p => h(p.name)).join(' · ')}</span></div>${page.sections.length ? page.sections.map(section => {const title = h(section.title || 'Your heading'); const body = h(section.body || 'Describe what belongs here.'); const cta = h(section.cta || 'Continue'); if (section.kind === 'hero') return `<section class="hero"><h2>${title}</h2><p>${body}</p><span class="cta">${cta}</span></section>`; if (section.kind === 'cards') return `<section class="cards"><h2>${title}</h2><p>${body}</p><div class="card-row"><div>First idea</div><div>Second idea</div><div>Third idea</div></div></section>`; if (section.kind === 'form') return `<section class="form-mock"><h2>${title}</h2><p>${body}</p><span class="fake-input">${cta}</span><span class="cta">Submit</span></section>`; return `<section class="content"><h2>${title}</h2><p>${body}</p>${section.cta ? `<span class="cta">${cta}</span>` : ''}</section>`; }).join('') : '<div class="blank">Blank page — add a section in the editor.</div>'}<footer>Page mockup · ${h(page.name)}</footer></div>`;
}
function renderFlows() {
  if (!state.flows.length) return `<div class="actions"><button class="btn green" data-action="new-flow">+ New flow</button></div>${empty('No flows yet','A flow is an ordered journey through page mockups. You can create one without Vision stories.','new-flow','Create a flow')}`;
  const flow = findFlow(ui.flow) || state.flows[0]; ui.flow = flow.id; ui.step = Math.min(ui.step, Math.max(0, flow.steps.length - 1));
  const step = flow.steps[ui.step]; const page = step && findPage(step.page);
  return `<div class="actions"><label class="small">Flow <select data-field="flow-select">${state.flows.map(f => `<option value="${h(f.id)}" ${f.id === flow.id ? 'selected' : ''}>${h(f.name)}</option>`).join('')}</select></label><button class="btn" data-action="new-flow">+ Flow</button>${badge(flow.reviewed ? 'Reviewed' : 'Draft',flow.reviewed ? 'green' : 'warn')}</div><div class="flow-editor"><div class="card"><h2>Journey steps</h2><label class="field"><span>Name</span><input data-flow-field="name" value="${h(flow.name)}" maxlength="80"></label><label class="field"><span>Goal</span><textarea data-flow-field="goal">${h(flow.goal)}</textarea></label><div class="step-list">${flow.steps.map((item,index) => `<div class="step-item ${ui.step === index ? 'active' : ''}"><button class="step-select" data-action="select-step" data-index="${index}">${index + 1}. ${h(findPage(item.page)?.name || 'Choose a page')}</button><label class="field"><span>Page</span><select data-step-field="page" data-index="${index}">${pageOptions(item.page)}</select></label><label class="field"><span>Related story (optional)</span><select data-step-field="story" data-index="${index}"><option value="">No story linked</option>${stories().map(story => `<option value="${h(story.id)}" ${item.story === story.id ? 'selected' : ''}>${h(story.title)}</option>`).join('')}</select></label><label class="field"><span>What happens next</span><input data-step-field="note" data-index="${index}" value="${h(item.note)}" placeholder="e.g. Selects a plan"></label><div class="controls"><button data-action="move-step" data-index="${index}" data-dir="-1" aria-label="Move step up">↑</button><button data-action="move-step" data-index="${index}" data-dir="1" aria-label="Move step down">↓</button><button data-action="remove-step" data-index="${index}">Remove</button></div></div>`).join('')}</div><div class="actions"><button class="btn green" data-action="add-step">+ Step</button></div></div><div class="stack"><div class="row space"><h2>Walkthrough</h2><label class="toggle"><input type="checkbox" data-field="phone" ${ui.phone ? 'checked' : ''}> Phone width</label></div><div class="preview-stage">${flow.steps.length ? mockup(page,ui.phone) : '<div class="empty"><h2>Add a first step</h2><p>Choose a page to start walking this journey.</p></div>'}</div><div class="actions"><button class="btn" data-action="prev-step" ${ui.step === 0 ? 'disabled' : ''}>← Previous</button><span class="muted">${flow.steps.length ? `Step ${ui.step + 1} of ${flow.steps.length}` : 'No steps'}</span><button class="btn" data-action="next-step" ${ui.step >= flow.steps.length - 1 ? 'disabled' : ''}>Next →</button></div></div><div class="card"><h2>Review the flow</h2><p class="muted">${h(flow.goal || 'What should a person accomplish? Add a goal.')}</p><div class="divider"></div><p>${step ? h(step.note || 'Describe the transition from this step.') : 'The journey has no steps yet.'}</p><label class="field"><span>Review note</span><textarea data-flow-field="reviewNote" placeholder="What works or needs revision?">${h(flow.reviewNote || '')}</textarea></label><button class="btn ${flow.reviewed ? '' : 'green'}" data-action="toggle-review">${flow.reviewed ? 'Reopen review' : 'Mark reviewed'}</button><p class="small muted">A review is your judgment in this prototype. It does not accept code or publish a site.</p></div></div>`;
}
function knowledgeRows() {
  return [ ...state.pages.map(page => ({ type:'Page',title:page.name,detail:page.note || page.path,source:'Pages · owned',ref:`page:${page.id}` })), ...state.flows.map(flow => ({ type:'Flow',title:flow.name,detail:flow.goal,source:'Pages · owned',ref:`flow:${flow.id}` })), ...state.layers.flatMap(layer => layer.records.map(record => ({ type:layer.type === 'vision' ? 'Story' : layer.output, title:record.title,detail:record.detail,source:`${layer.name} · owned`,ref:`record:${layer.id}:${record.id}` }))), ...state.sources.map(source => ({ type:'Source',title:source.title,detail:source.detail,source:'Library · source',ref:`source:${source.id}` })), ...state.insights.map(insight => ({ type:'Insight',title:insight.title,detail:insight.detail,source:'Library · insight',ref:`insight:${insight.id}` })) ];
}
function renderLibrary() {
  const list = knowledgeRows().filter(row => !ui.query || `${row.type} ${row.title} ${row.detail} ${row.source}`.toLowerCase().includes(ui.query.toLowerCase()));
  return `<div class="eyebrow" style="color:var(--purple)">Shared service · Library</div><h1>Project knowledge</h1><p class="lead">Find layer outputs, sources and insights in one place. The owner of each output stays visible. Agents would use a scoped knowledge gateway behind this view.</p>${tabs([['all','All knowledge'],['sources','Sources & insights'],['access','Access model']],ui.tab,true)}${ui.tab === 'sources' ? `<div class="grid two"><div class="card"><h2>Add a source</h2><form id="source-form"><label class="field"><span>Title</span><input name="title" required maxlength="90"></label><label class="field"><span>Link or origin</span><input name="origin" maxlength="180" placeholder="URL, interview, file, observation…"></label><label class="field"><span>What does it say?</span><textarea name="detail" maxlength="1000"></textarea></label><label class="field"><span>Connect to</span><select name="ref">${refOptions()}</select></label><button class="btn primary" type="submit">Save source</button></form></div><div class="card"><h2>Add an insight</h2><form id="insight-form"><label class="field"><span>Claim</span><input name="title" required maxlength="120"></label><label class="field"><span>Reasoning or uncertainty</span><textarea name="detail" maxlength="1000"></textarea></label><label class="field"><span>Connect to</span><select name="ref">${refOptions()}</select></label><button class="btn primary" type="submit">Save insight</button></form></div></div><div class="card" style="margin-top:14px"><h2>Research and insight records</h2>${[...state.sources.map(x=>({ ...x,type:'Source' })),...state.insights.map(x=>({ ...x,type:'Insight' }))].map(x=>`<div class="list-item">${badge(x.type,'pink')} <strong>${h(x.title)}</strong><p>${h(x.detail)}</p><span class="small muted">${h(x.origin || x.ref || 'No source link')}</span></div>`).join('') || '<p class="muted">None yet. Pages works without research records, but you can add evidence as you learn.</p>'}</div>` : ui.tab === 'access' ? `<div class="grid two"><div class="card"><h2>Knowledge gateway</h2><p>One project-scoped read interface would discover output descriptors, fetch exact revisions and follow typed links. Library is its human-facing search and research workspace; it is not the author of other layers' records.</p><dl class="kv"><dt>Identity</dt><dd>Each result names its owning layer or Library source record.</dd><dt>Scope</dt><dd>Project membership and role determine which records an agent may read.</dd><dt>Version</dt><dd>Work attempts pin the revisions they use.</dd></dl></div><div class="card"><h2>Sources stay shared</h2><p>Sources and insights are Library-owned evidence. Any layer may link to them, while a layer's output remains in that layer. A finding can inform several pages and flows without being copied into each as a second authority.</p><div class="notice warn">This local trial has no authentication or agent lookup API. The access model here is a design fixture.</div></div></div>` : `<div class="actions"><button class="btn" data-action="tab" data-tab="sources">+ Source or insight</button><span class="muted small">${list.length} visible record${list.length === 1 ? '' : 's'}</span></div>${list.length ? `<div class="grid two">${list.map(row => `<div class="card"><div class="row space">${badge(row.type,row.type === 'Page' || row.type === 'Flow' ? 'green' : row.type === 'Story' ? 'blue' : 'pink')}<span class="small muted">${h(row.source)}</span></div><h3>${h(row.title)}</h3><p class="muted">${h(row.detail || 'No summary yet')}</p><span class="small muted">${h(row.ref)}</span></div>`).join('')}</div>` : empty('No matching knowledge','Create a page, flow, source or insight. Search will include outputs from any layer you add.',null,null)}`}`;
}
function renderWork() {
  return `<div class="eyebrow" style="color:var(--purple)">Permanent service · Work</div><h1>Work and scheduling</h1><p class="lead">Layer routines can suggest work here. You choose what to start and review. Agent execution would be configured here, outside every layer app.</p>${tabs([['items','Items'],['execution','Execution']],ui.tab,true)}${ui.tab === 'execution' ? `<div class="grid two"><div class="card"><h2>Who performs agent work?</h2><p>Work would hand authorized agent items to Symphony. Profiles choose the provider, model and effort; Symphony workers provide capacity. Pages decides what work is useful, not how it runs.</p><label class="field"><span>Orchestrator</span><select disabled><option>Symphony</option></select></label><label class="toggle"><input type="checkbox" data-field="agent-enabled" ${state.execution.agentEnabled ? 'checked' : ''}> Show agent execution as configured</label><p class="small muted">This trial has no worker or provider connection. Toggling this only changes this explanatory setting; it cannot run a task.</p></div><div class="card"><h2>Permanent boundary</h2><dl class="kv"><dt>Work owns</dt><dd>Task state, run authorization, questions, scheduling, attempts and review.</dd><dt>Layer owns</dt><dd>Its relevance rules, candidate output and quality checks.</dd><dt>Knowledge</dt><dd>A scoped gateway resolves source and layer records into pinned task context.</dd></dl></div></div>` : `<div class="grid side"><div class="stack"><div class="card"><div class="row space"><h2>Items</h2>${badge(`${state.work.filter(x=>x.status==='suggested').length} suggested`,'purple')}</div>${state.work.length ? state.work.map(item => `<div class="list-item"><div class="row space"><strong>${h(item.title)}</strong>${badge(item.status,item.status === 'done' ? 'green' : item.status === 'superseded' ? '' : 'purple')}</div><p>${h(item.detail)}</p><span class="meta">${h(item.layer || 'You')} · ${h(item.target || 'general')} · ${h(item.created)}</span><div class="actions">${item.runId || item.target && item.target !== 'General' ? `<button class="btn" data-action="work-open" data-id="${h(item.id)}">${item.runId ? 'Examine run' : item.layer==='Pages' && item.target.startsWith('record:') ? 'Draft flow' : 'Open target'}</button>` : ''}${item.status === 'suggested' ? `<button class="btn" data-action="work-status" data-id="${h(item.id)}" data-status="ready">Keep for later</button><button class="btn" data-action="work-status" data-id="${h(item.id)}" data-status="dismissed">Dismiss</button>` : item.status === 'ready' ? `<button class="btn green" data-action="work-status" data-id="${h(item.id)}" data-status="done">Mark done</button>` : ''}</div></div>`).join('') : '<p class="muted">No work yet. Add your own task or let a Pages routine suggest one.</p>'}</div></div><div class="stack"><div class="card"><h2>Add your own work</h2><form id="work-form"><label class="field"><span>Task</span><input name="title" required maxlength="140" placeholder="e.g. Sketch the signup journey"></label><label class="field"><span>What should be produced?</span><textarea name="detail" maxlength="800"></textarea></label><button class="btn primary" type="submit">Add task</button></form></div><div class="card soft"><h3>Routines do not dispatch</h3><p>Pages routines create run items and output tasks here. Work would schedule an agent only after authorization.</p><button class="btn" data-action="nav" data-view="pages" data-tab="operations" data-operation="routines">Open Pages routines</button></div></div></div>`}`;
}
function renderAddLayer() {
  return `<div class="eyebrow">Project structure</div><h3>Add a layer app</h3><p class="muted">Give a new layer an output it owns. Pages will discover its descriptor, then decide whether that output can inform page or flow work.</p><div class="grid two"><div class="card"><form id="layer-form"><label class="field"><span>Starting type</span><select name="type"><option value="vision">Vision · publishes stories</option><option value="custom">Custom · publishes notes</option></select></label><label class="field"><span>Layer name</span><input name="name" maxlength="60" placeholder="Vision, Analytics, Campaigns…"></label><label class="field"><span>What does it maintain?</span><textarea name="purpose" maxlength="500" placeholder="A coherent family of outputs"></textarea></label><label class="toggle small"><input type="checkbox" name="homeCard" checked> Show a card on Home</label><button class="btn primary" type="submit">Add layer</button></form></div><div class="card soft"><h2>After it appears</h2><p>The new layer publishes its output identity and records to project discovery. Pages sees a candidate neighbor, not an obligation to change its policy. You can inspect the connection in Pages › Operations › Connections.</p><div class="notice warn">This prototype supports story matching from Vision. A custom layer exposes searchable notes but has no invented Pages relation.</div></div></div>`;
}
function renderLayer(layer) {
  if(!layer)return empty('Layer unavailable','Choose a layer from the rail.',null,null);
  layer.knowledge ||= [{id:'output',title:`${layer.output} output specification`,content:`${layer.name} owns ${layer.output} records for this project. Other layers may discover their identity and revisions.`,revision:1},{id:'expert',title:`${layer.name} expert instructions`,content:`Use this layer's ${layer.output} output and scoped project knowledge. Submit changes through Work for review.`,revision:1}];
  const section=ui.tab||'output';
  const nav=`<div class="layer-tabs" role="tablist" aria-label="${h(layer.name)} layer sections"><div class="layer-work-tabs"><button role="tab" aria-selected="${section==='output'}" data-action="tab" data-tab="output">${layer.type==='vision'?'Stories':'Notes'}</button></div><div class="layer-manage-tabs"><button role="tab" aria-selected="${section==='operations'}" data-action="tab" data-tab="operations">Operations</button><button role="tab" aria-selected="${section==='knowledge'}" data-action="tab" data-tab="knowledge">Knowledge</button></div></div>`;
  const output=`<div class="grid side"><div class="card"><h2>${layer.type==='vision'?'Stories':'Notes'}</h2>${layer.records.length?layer.records.map(record=>`<div class="list-item"><strong>${h(record.title)}</strong><label class="field"><span>Description</span><textarea data-record-field="detail" data-layer="${h(layer.id)}" data-id="${h(record.id)}">${h(record.detail)}</textarea></label><span class="small muted">Owned by ${h(layer.name)} · ${h(record.id)}</span></div>`).join(''):`<p class="muted">No ${h(layer.output)} yet.</p>`}</div><div class="stack"><div class="card"><h2>Add ${layer.type==='vision'?'a story':'a note'}</h2><form id="layer-record-form" data-layer="${h(layer.id)}"><label class="field"><span>Title</span><input name="title" required maxlength="100"></label><label class="field"><span>${layer.type==='vision'?'Situation and outcome':'Description'}</span><textarea name="detail" maxlength="800"></textarea></label><button class="btn primary" type="submit">Save ${layer.type==='vision'?'story':'note'}</button></form></div><div class="card soft"><h3>Published output</h3><p>Type: ${h(layer.output)}. Library can find these records. Pages may propose a relationship to them, but does not inherit their authority.</p><button class="btn" data-action="nav" data-view="pages" data-tab="operations" data-operation="connections">See Pages connections</button></div></div></div>`;
  const work=state.work.filter(item=>item.layer===layer.name);
  const operations=`<div class="ops-heading"><div><h2>Layer operations</h2><p class="muted">Work and routines owned by ${h(layer.name)}.</p></div>${badge(`${work.filter(x=>['suggested','ready'].includes(x.status)).length} open`,'purple')}</div><div class="operations-layout"><section><h2>${h(layer.name)} work</h2><div class="work-card-stack">${work.length?work.map(item=>`<article class="work-card"><div class="work-card-top">${badge(item.kind==='routine'?'Routine run':'Output task','blue')}${badge(item.status,item.status==='done'?'green':'purple')}</div><h3>${h(item.title)}</h3><p>${h(item.detail||'')}</p><div class="work-card-bottom"><span class="small muted">${h(item.created||'')}</span>${item.target?.startsWith('record:')?`<button class="btn" data-action="work-open" data-id="${h(item.id)}">Open target</button>`:''}</div></article>`).join(''):'<div class="empty"><h3>No layer work</h3><p>Run the layer audit or add output records to begin.</p></div>'}</div></section><aside class="ops-sidebar"><div class="card"><h3>Routines</h3><p class="small muted">Check ${h(layer.output)} records for missing descriptions. A local utility stages or closes work.</p><button class="btn" data-action="scan-layer" data-id="${h(layer.id)}">Run description audit</button><p class="small muted">${layer.audit?`Last run: ${h(layer.audit.at)} · ${layer.audit.gaps} gaps`:'No audit run yet.'}</p></div><div class="card"><h3>Connections</h3><p class="small muted">This layer publishes ${h(layer.output)}. Cross-layer interpretation is managed in the receiving layer.</p><button class="btn" data-action="nav" data-view="pages" data-tab="operations" data-operation="connections">View Pages connection</button></div></aside></div>`;
  const selected=layer.knowledge.find(doc=>doc.id===ui.layerDoc)||layer.knowledge[0];
  const knowledge=`<div class="row space"><div><h2>Internal knowledge</h2><p class="muted">Output specification and expert instructions for this layer.</p></div>${badge(`${layer.knowledge.length} documents`,'blue')}</div><div class="doc-explorer"><aside class="card tree-panel"><h3>${h(layer.name)} documents</h3>${layer.knowledge.map(doc=>`<button class="tree-link ${selected.id===doc.id?'active':''}" data-action="layer-doc" data-id="${h(doc.id)}">${h(doc.title)} <small>r${doc.revision}</small></button>`).join('')}</aside><article class="card doc-body"><h2>${h(selected.title)}</h2><p class="small muted">${h(layer.name)} authority · revision ${selected.revision}</p><form id="layer-knowledge-form" data-layer="${h(layer.id)}" data-id="${h(selected.id)}"><label class="field"><span>Document</span><textarea name="content" class="tall doc-edit">${h(selected.content)}</textarea></label><button class="btn primary" type="submit">Save new revision</button></form></article></div>`;
  return `<div class="eyebrow" style="color:#8a6100">Project layer app</div><h1>${h(layer.name)}</h1><p class="lead">${h(layer.purpose||`Maintains ${layer.output} for this project.`)}</p>${nav}${section==='operations'?operations:section==='knowledge'?knowledge:output}`;
}
function go(view,tab,selected) { ui.view=view;ui.tab=tab||(view==='pages'?'map':view==='library'?'all':view==='work'?'items':view==='home'?'':'output');if(view==='pages'&&tab==='pages')ui.page=selected||ui.page;if(view==='pages'&&tab==='flows'){ui.flow=selected||ui.flow;ui.step=0;}window.scrollTo(0,0);render(); }
root.addEventListener('click', event => {
  const button = event.target.closest('[data-action]'); if (!button) return;
  const action = button.dataset.action; const key = button.dataset.id; const flow = findFlow(ui.flow);
  if (action === 'nav') { if(button.dataset.openAdd==='true')ui.homeAdding=true; if(button.dataset.operation)ui.operation=button.dataset.operation;else if(button.dataset.tab==='operations')ui.operation='board';return go(button.dataset.view,button.dataset.tab); }
  if (action === 'tab') { if(button.dataset.tab==='operations'&&ui.tab!=='operations'){ui.operation='board';ui.routine=null;ui.run=null;ui.connection=null;} return go(ui.view,button.dataset.tab,ui.tab==='pages'?ui.page:ui.flow); }
  if (action === 'home-add-layer') { ui.homeAdding=!ui.homeAdding;return render(); }
  if (action === 'operation') { ui.operation=button.dataset.operation;ui.routine=null;ui.run=null;ui.connection=null;return render(); }
  if (action === 'layer-doc') { ui.layerDoc=key;return render(); }
  if (action === 'search') return go('library','all');
  if (action === 'output-doc') { ui.outputDoc=key; return render(); }
  if (action === 'output-back') { ui.outputDoc=null; return render(); }
  if (action === 'open-knowledge-doc') { ui.doc=key; return go('pages','knowledge'); }
  if (action === 'knowledge-doc') { ui.doc=key; return render(); }
  if (action === 'open-routine') { ui.routine=key;ui.run=null;ui.operation='routines';return go('pages','operations'); }
  if (action === 'routine-back') { ui.routine=null; ui.run=null; return render(); }
  if (action === 'run-routine') { const run=runPagesRoutine(state,key); if(run){ui.routine=key;ui.run=run.id;ui.operation='routines';save();go('pages','operations');} return; }
  if (action === 'open-run') { const run=state.pagesApp.runs.find(x=>x.id===key); if(!run)return; ui.routine=run.routineId;ui.run=key;ui.operation='routines';return go('pages','operations'); }
  if (action === 'demo-run') { if(demonstrateAgentRun(state,key)){save();render();} return; }
  if (action === 'new-routine') { ui.operation='routines'; const key=id('routine'),docId=id('routine-doc');state.pagesApp.documents.push({id:docId,group:'Routines',title:'New routine instructions',content:'Describe the inputs, decisions, and allowed results of this routine.',revision:1});state.pagesApp.routines.push({id:key,title:'New routine',executor:'agent',trigger:'On demand',enabled:true,documentId:docId,capabilities:['Read scoped knowledge'],outputKinds:['Run report'],revision:1});ui.routine=key;save();return render(); }
  if (action === 'open-connection') { ui.connection=key;ui.operation='connections';return go('pages','operations'); }
  if (action === 'connection-back') { ui.connection=null;return render(); }
  if (action === 'draft-connection') { const layer=findLayer(key);if(!layer)return;const connection={id:id('connection'),layerId:layer.id,title:`${layer.name} → Pages`,sourceOutput:layer.output,status:'proposed',mapping:'reference-only',instructions:'Describe which source records Pages may use and why.',reaction:'On source change, compare against Pages outputs before staging work.',question:'',answer:'',revision:1};state.pagesApp.connections.push(connection);ui.connection=connection.id;ui.operation='connections';save();return go('pages','operations'); }
  if (action === 'activate-connection') { const connection=state.pagesApp.connections.find(x=>x.id===key);if(!connection)return;if(connection.question.trim()&&!connection.answer.trim())return alert('Answer the open question before activation.');updateConnection(state,key,{status:'active'});queueSync('Connection activated');save();return render(); }
  if (action === 'deactivate-connection') { updateConnection(state,key,{status:'inactive'});save();return render(); }

  if (action === 'new-page') { const page = { id:id('page'), name:`Page ${state.pages.length + 1}`, path:`/page-${state.pages.length + 1}`, note:'', sections:[] }; state.pages.push(page); save(); return go('pages','pages',page.id); }
  if (action === 'open-page') return go('pages','pages',key);
  if (action === 'new-flow') { const item={ id:id('flow'), name:`Flow ${state.flows.length + 1}`, goal:'', steps:[], reviewed:false, reviewNote:'' }; state.flows.push(item); save(); return go('pages','flows',item.id); }
  if (action === 'open-flow') return go('pages','flows',key);
  if (action === 'add-section') { const page=findPage(ui.page); if (!page) return; page.sections.push({id:id('section'),kind:'hero',title:'',body:'',cta:''}); save(); return render(); }
  if (action === 'remove-section') { const page=findPage(ui.page); if (!page) return; page.sections=page.sections.filter(x=>x.id!==key); save(); return render(); }
  if (action === 'add-step' && flow) { flow.steps.push({page:state.pages[0]?.id||'', note:'', story:''}); ui.step=flow.steps.length-1; flow.reviewed=false; save(); return render(); }
  if (action === 'select-step') { ui.step=Number(button.dataset.index); return render(); }
  if (action === 'prev-step') { ui.step=Math.max(0,ui.step-1); return render(); }
  if (action === 'next-step' && flow) { ui.step=Math.min(flow.steps.length-1,ui.step+1); return render(); }
  if (action === 'move-step' && flow) { const from=Number(button.dataset.index), to=from+Number(button.dataset.dir); if(to<0||to>=flow.steps.length)return; [flow.steps[from],flow.steps[to]]=[flow.steps[to],flow.steps[from]]; ui.step=to; flow.reviewed=false; save(); return render(); }
  if (action === 'remove-step' && flow) { flow.steps.splice(Number(button.dataset.index),1); ui.step=Math.max(0,Math.min(ui.step,flow.steps.length-1)); flow.reviewed=false; save(); return render(); }
  if (action === 'toggle-review' && flow) { if (!flow.steps.length) return alert('Add a step before reviewing this flow.'); flow.reviewed=!flow.reviewed; save(); return render(); }
  if (action === 'work-open') { const item=state.work.find(x=>x.id===key); if(!item)return; if(item.runId){if(item.layer!=='Pages')return go(state.layers.find(x=>x.name===item.layer)?.id||'home','operations');ui.routine=item.routineId;ui.run=item.runId;ui.operation='routines';return go('pages','operations');} const [type,target,recordId]=String(item.target||'').split(':'); if(type==='record'&&item.layer==='Pages'){const layer=findLayer(target),record=layer?.records.find(x=>x.id===recordId);if(!record)return;const draft={id:id('flow'),name:`Explore ${record.title}`.slice(0,80),goal:record.detail||record.title,steps:[{page:state.pages[0]?.id||'',note:'',story:layer.type==='vision'?record.id:'',sourceRef:`record:${layer.id}:${record.id}`}],reviewed:false,reviewNote:''};state.flows.push(draft);save();return go('pages','flows',draft.id);} if(type==='record')return go(target); if(type==='page')return go('pages','pages',target); if(type==='flow')return go('pages','flows',target); return; }
  if (action === 'scan-layer') { const layer=findLayer(key);if(!layer)return;const gaps=layer.records.filter(record=>!record.detail.trim()).map(record=>({key:`layer-detail:${layer.id}:${record.id}`,title:`Describe ${record.title}`,detail:`${layer.name} description audit · this ${layer.output} has no description.`,target:`record:${layer.id}:${record.id}`}));const active=new Set(gaps.map(gap=>gap.key)),created=[];for(const gap of gaps)if(!state.work.some(item=>item.gap===gap.key&&['suggested','ready'].includes(item.status))){const item={id:id('work'),kind:'output',...gap,gap:gap.key,layer:layer.name,status:'suggested',created:date()};state.work.unshift(item);created.push(item.id);}for(const item of state.work)if(item.gap?.startsWith(`layer-detail:${layer.id}:`)&&!active.has(item.gap)&&['suggested','ready'].includes(item.status))item.status='resolved';const runId=id('run');layer.runs||=[];layer.runs.unshift({id:runId,at:date(),summary:`Checked ${layer.records.length} ${layer.output} records; staged ${created.length} task(s).`,outputs:created});state.work.unshift({id:id('work'),kind:'routine',layer:layer.name,runId,title:`${layer.name} description audit`,detail:layer.runs[0].summary,status:'done',created:date(),target:'General'});layer.audit={at:date(),gaps:gaps.length};save();return render(); }
  if (action === 'work-status') { const item=state.work.find(x=>x.id===key); if(item){item.status=button.dataset.status;save();render();} return; }
  if (action === 'reset') { if (!confirm('Reset this local trial? This removes its pages, flows, Library records, layers and Work items from this browser.')) return; state=fresh(); ensureLayerModel(state); clearTimeout(mapTimer); lastOutputSignature=JSON.stringify([state.pages,state.flows]); save(); ui.homeAdding=false;return go('home'); }
});
root.addEventListener('submit', event => { event.preventDefault(); const form=event.target; const values=new FormData(form);
  if(form.id==='routine-form'){const key=form.dataset.id,routine=state.pagesApp.routines.find(x=>x.id===key);if(!routine)return;updateRoutine(state,key,{title:String(values.get('title')).trim(),executor:String(values.get('executor')),trigger:String(values.get('trigger')),capabilities:String(values.get('capabilities')||'').split('\n').map(x=>x.trim()).filter(Boolean),outputKinds:String(values.get('outputs')||'').split('\n').map(x=>x.trim()).filter(Boolean)});const instructions=String(values.get('instructions')||'');const doc=state.pagesApp.documents.find(x=>x.id===routine.documentId);if(doc?.content!==instructions)updateDocument(state,routine.documentId,{content:instructions});save();return render();}
  if(form.id==='connection-form'){const key=form.dataset.id,connection=state.pagesApp.connections.find(x=>x.id===key);if(!connection)return;const patch={mapping:String(values.get('mapping')),instructions:String(values.get('instructions')||''),reaction:String(values.get('reaction')||''),question:String(values.get('question')||''),answer:String(values.get('answer')||'')};if(connection.status==='active'&&Object.entries(patch).some(([name,value])=>connection[name]!==value))patch.status='proposed';updateConnection(state,key,patch);save();return render();}
  if(form.id==='knowledge-form'){updateDocument(state,form.dataset.id,{content:String(values.get('content')||'')});save();return render();}
  if(form.id==='layer-knowledge-form'){const layer=findLayer(form.dataset.layer),doc=layer?.knowledge?.find(x=>x.id===form.dataset.id);if(doc){doc.content=String(values.get('content')||'');doc.revision++;save();render();}return;}
  if(form.id==='project-form'){state.project=String(values.get('name')||'Untitled site').trim();save();return render();}
  if(form.id==='work-form'){state.work.push({id:id('work'),title:String(values.get('title')).trim(),detail:String(values.get('detail')||'').trim(),target:'General',layer:'You',status:'ready',created:date()});save();return render();}
  if(form.id==='source-form'){state.sources.push({id:id('source'),title:String(values.get('title')).trim(),origin:String(values.get('origin')||'').trim(),detail:String(values.get('detail')||'').trim(),ref:String(values.get('ref')||'')});save();return render();}
  if(form.id==='insight-form'){state.insights.push({id:id('insight'),title:String(values.get('title')).trim(),detail:String(values.get('detail')||'').trim(),ref:String(values.get('ref')||'')});save();return render();}
  if(form.id==='layer-form'){const type=String(values.get('type'));const name=String(values.get('name')||'').trim() || (type==='vision'?'Vision':'New layer'); const layer={id:id('layer'),type,name,purpose:String(values.get('purpose')||'').trim(),output:type==='vision'?'story':'note',records:[],homeCard:values.has('homeCard')};state.layers.push(layer);queueLayerDiscovery(state,layer);save();return go(layer.id);}
  if(form.id==='layer-record-form'){const layer=findLayer(form.dataset.layer);if(!layer)return;layer.records.push({id:id(layer.type==='vision'?'story':'note'),title:String(values.get('title')).trim(),detail:String(values.get('detail')||'').trim()});queueSync(`${layer.name} output changed`);save();return render();}
});
root.addEventListener('change', event => { const el=event.target;
  if(el.dataset.field==='home-card'){const layer=findLayer(el.dataset.id);if(layer){layer.homeCard=el.checked;save();render();}return;}
  if(el.dataset.field==='board-filter'){ui.boardFilter=el.value;return render();}
  if(el.dataset.field==='run-filter'){ui.runFilter=el.value;return render();}
  if(el.dataset.field==='routine-enabled'){const routine=state.pagesApp.routines.find(x=>x.id===el.dataset.id);if(routine){updateRoutine(state,routine.id,{enabled:el.checked});save();render();}return;}
  if(el.dataset.field==='page-select') return go('pages','pages',el.value);
  if(el.dataset.field==='flow-select') return go('pages','flows',el.value);
  if(el.dataset.field==='phone'){ui.phone=el.checked;return render();}
  if(el.dataset.field==='agent-enabled'){state.execution.agentEnabled=el.checked;save();return render();}
  if(el.dataset.recordField){const layer=findLayer(el.dataset.layer),record=layer?.records.find(x=>x.id===el.dataset.id);if(record){record[el.dataset.recordField]=el.value;if(el.dataset.recordField==='detail'&&record.detail.trim())for(const item of state.work)if(item.gap===`layer-detail:${layer.id}:${record.id}`&&['suggested','ready'].includes(item.status))item.status='resolved';queueSync(`${layer.name} output changed`);save();render();}return;}
  if(el.dataset.pageField){const page=findPage(ui.page);if(page){page[el.dataset.pageField]=el.value;save();render();}return;}
  if(el.dataset.sectionField){const page=findPage(ui.page),section=page?.sections.find(x=>x.id===el.dataset.id);if(section){section[el.dataset.sectionField]=el.value;save();render();}return;}
  if(el.dataset.flowField){const flow=findFlow(ui.flow);if(flow){flow[el.dataset.flowField]=el.value;if(el.dataset.flowField!=='reviewNote')flow.reviewed=false;save();render();}return;}
  if(el.dataset.stepField){const flow=findFlow(ui.flow),step=flow?.steps[Number(el.dataset.index)];if(step){step[el.dataset.stepField]=el.value;flow.reviewed=false;save();render();}return;}
});
root.addEventListener('input', event => {if(event.target.dataset.field==='search'){ui.query=event.target.value;}});
render();
